/**
 * One NONE transaction that adds a whole in-memory collection writes it as one prepared chunk, the way a READ_COMMITTED
 * commit writes its buffered statements, and keeps every guarantee of the per-statement path.
 */
@Timeout(value = 2, unit = TimeUnit.MINUTES)
class LmdbNoneBulkApproveTest {

	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final String NS = "http://example.org/none-bulk/";
	private static final IRI GRAPH = F.createIRI(NS + "graph");
	private static final int SIZE = 20_000;

	@TempDir
	File dataDir;

	private SailRepository repo;
	private LmdbStore store;

	@AfterEach
	void tearDown() {
		if (repo != null) {
			repo.shutDown();
		}
	}

	@Test
	void aCollectionIntoAnEmptyStoreIsWrittenAsOnePreparedChunk() {
		open(config());
		load(model("first", 0, SIZE));
		assertThat(store.getBackingStore().preparedNoneChunks()).as("the collection took the prepared path")
				.isEqualTo(1);
		assertThat(store.getBackingStore().initialRunImportsCompleted()).as("it claimed no run import").isZero();
	}

	@Test
	void aCollectionIsStoredWithOneIdPerValue() {
		open(config());
		Model first = model("first", 0, SIZE);
		load(first);
		assertStored(first);
		reopen(config());
		assertStored(first);
	}

	@Test
	void aSecondCollectionOverlappingTheFirstKeepsOneIdPerValue() {
		open(config());
		Model first = model("first", 0, SIZE);
		Model second = model("second", SIZE / 2, SIZE + SIZE / 2);
		load(first);
		load(second);
		Model all = new LinkedHashModel(first);
		all.addAll(second);
		assertStored(all);
		reopen(config());
		assertStored(all);
	}

	@Test
	void aRolledBackCollectionLeavesAConsistentStore() {
		open(config());
		Model first = model("first", 0, SIZE);
		load(first);
		Model kept = new LinkedHashModel();
		try (SailRepositoryConnection connection = repo.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			connection.add(model("rolled-back", SIZE / 2, SIZE + SIZE / 2));
			connection.rollback();
			// NONE may keep part of a rolled-back transaction (IsolationLevels.NONE); take what the store kept.
			try (RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
				statements.forEach(kept::add);
			}
		}
		Model third = model("third", SIZE / 4, SIZE);
		load(third);
		kept.addAll(third);
		assertStored(kept);
		reopen(config());
		assertStored(kept);
	}

	@Test
	void adjacencyAnswersMatchTheStoreAfterACollection() {
		open(config().setDirectAdjacencyEnabled(true).setDirectAdjacencyMode(DirectAdjacencyMode.PREFER));
		Model first = model("first", 0, SIZE);
		load(first);
		assertThat(store.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS))
				.as(store.getDirectAdjacencyReadinessDescription())
				.isTrue();
		assertStored(first);
	}

	@Test
	void aListenerSeesEveryStatementOfTheCollection() {
		open(config());
		Model first = model("first", 0, SIZE);
		AtomicLong added = new AtomicLong();
		try (SailRepositoryConnection connection = repo.getConnection()) {
			((LmdbStoreConnection) connection.getSailConnection()).addConnectionListener(new SailConnectionListener() {
				@Override
				public void statementAdded(Statement statement) {
					added.incrementAndGet();
				}

				@Override
				public void statementRemoved(Statement statement) {
				}
			});
			connection.begin(IsolationLevels.NONE);
			connection.add(first);
			connection.commit();
		}
		assertThat(added.get()).isEqualTo(first.size());
		assertStored(first);
	}

	@Test
	void aCollectionThatFillsTheMapsIsReplayedIntoGrownMaps() {
		LmdbStoreConfig small = config().setValueDBSize(1L << 20).setTripleDBSize(1L << 20);
		open(small);
		Model first = model("first", 0, SIZE);
		load(first);
		assertStored(first);
		reopen(small);
		assertStored(first);
	}

	private void open(LmdbStoreConfig config) {
		store = new LmdbStore(dataDir, config);
		repo = new SailRepository(store);
		repo.init();
	}

	private void reopen(LmdbStoreConfig config) {
		repo.shutDown();
		open(config);
	}

	private void load(Model model) {
		try (SailRepositoryConnection connection = repo.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			connection.add(model);
			connection.commit();
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,ospc,psoc").setSketchEstimatorEnabled(false).setValueOverlayEnabled(false);
	}

	/**
	 * Subjects are unique per statement, five predicates are shared by all, one object in ten is shared by many
	 * statements and the rest are literals unique to their index; every fourth statement is in a named graph.
	 */
	private static Model model(String batch, int from, int to) {
		Model model = new LinkedHashModel();
		for (int i = from; i < to; i++) {
			IRI subject = F.createIRI(NS + batch + "/s" + i);
			IRI predicate = F.createIRI(NS + "p" + (i % 5));
			Value object = i % 10 == 0 ? F.createIRI(NS + "shared/o" + (i % 100))
					: F.createLiteral("an object that is longer than an inlined literal " + i);
			Resource context = i % 4 == 0 ? GRAPH : null;
			model.add(subject, predicate, object, context);
		}
		return model;
	}

	/** A value with two IDs splits its statements: a lookup by it finds only those written with one of the IDs. */
	private void assertStored(Model expected) {
		try (SailRepositoryConnection connection = repo.getConnection()) {
			Set<Statement> actual = new HashSet<>();
			try (RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
				statements.forEach(actual::add);
			}
			assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
			Map<Value, Long> byObject = new HashMap<>();
			expected.forEach(statement -> byObject.merge(statement.getObject(), 1L, Long::sum));
			for (Map.Entry<Value, Long> object : byObject.entrySet()) {
				try (RepositoryResult<Statement> statements = connection.getStatements(null, null, object.getKey(),
						false)) {
					assertThat(statements.stream().count()).as("statements found by %s", object.getKey())
							.isEqualTo(object.getValue());
				}
			}
			for (int p = 0; p < 5; p++) {
				IRI predicate = F.createIRI(NS + "p" + p);
				try (RepositoryResult<Statement> statements = connection.getStatements(null, predicate, null,
						false)) {
					assertThat(statements.stream().count()).as("statements found by %s", predicate)
							.isEqualTo(expected.filter(null, predicate, null).size());
				}
			}
			assertThat(connection.size(GRAPH)).isEqualTo(expected.filter(null, null, null, GRAPH).size());
		}
	}
}
